use nsbu_benchmarks::runtime_force::ForceSettings;
use nsbu_solver::{domain::{Domain, Layout, TickClock}, integrators::forcing::{ForceWork, PrescribedForce}, Complex64, SolverError};
use sha2::{Digest, Sha256}; use std::time::Instant;
const CAP:usize=1024*1024*1024; const END:u128=4096; const EARLY:u128=2047;
const ARCHIVED_2047:[u8;32]=[0x00,0x11,0x51,0x51,0xd9,0xc3,0xa5,0x88,0xd0,0x66,0x4b,0x5f,0xca,0x6c,0x84,0x81,0x3e,0x06,0xe4,0x20,0x11,0x26,0x01,0xb7,0x31,0xa8,0x60,0x13,0xb2,0x7e,0x57,0x22];
const ARCHIVED_4096:[u8;32]=[0x61,0xb0,0xa9,0xc9,0x9f,0xc8,0x7d,0x0b,0x68,0x2a,0x50,0x07,0x4b,0x36,0xa9,0xc3,0x93,0x8d,0x7f,0x86,0x04,0x58,0xfc,0x1d,0xcb,0x11,0x1e,0xad,0x69,0x05,0x4d,0x5f];
type Field=[Vec<Complex64>;3];
fn main()->Result<(),SolverError>{let dry=std::env::args().skip(1).collect::<Vec<_>>().as_slice()==["--dry-run"];let domain=Domain::new([24;3],[1.;3],1.)?;let settings=[ForceSettings{samples:Layout::new([192;3])?,workers:0},ForceSettings{samples:Layout::new([192;3])?,workers:12},ForceSettings{samples:Layout::new([192;3])?,workers:32}];let limits=[settings[0].limits(domain)?,settings[1].limits(domain)?,settings[2].limits(domain)?];let fields=3usize.checked_mul(3).and_then(|v|v.checked_mul(domain.layout().half_len())).and_then(|v|v.checked_mul(16)).ok_or(SolverError::SizeOverflow)?;let peak=limits[2].storage_bytes.checked_add(fields).and_then(|v|v.checked_add(4096)).ok_or(SolverError::SizeOverflow)?;let declared=limits[0].work_units.checked_add(limits[1].work_units).and_then(|v|v.checked_add(limits[2].work_units.checked_mul(3)?)).ok_or(SolverError::SizeOverflow)?;println!("preflight source=N24 samples=M192 workers=[0,12,32] endpoint={END} nonmonotone=[{EARLY},{END},{EARLY}] limits={limits:?} retained_fields_bytes={fields} sequential_peak_bytes={peak} cap={CAP} evaluations=5 declared_work={declared} declared_transforms=15");if peak>CAP{return Err(SolverError::ResourceLimit)}if dry{return Ok(())}
let (serial,sw,sd)=one(domain,settings[0],END)?;let(serial12,w12,d12)=one(domain,settings[1],END)?;let mut provider32=settings[2].build(domain,CAP)?;let(p32early,w32a,d32a)=evaluate(domain,&mut provider32,EARLY)?;let h32early=digest(&p32early);let early_archive=h32early==ARCHIVED_2047;let(p32end,w32end,d32end)=evaluate(domain,&mut provider32,END)?;let h32end=digest(&p32end);let end_archive=h32end==ARCHIVED_4096;let exact_serial32=exact(&serial,&p32end);let(p32repeat,w32repeat,d32repeat)=evaluate(domain,&mut provider32,EARLY)?;let h32repeat=digest(&p32repeat);println!("serial_endpoint work={sw:?} seconds={sd:.6} hash={:02x?}",digest(&serial));println!("workers12_endpoint work={w12:?} seconds={d12:.6} hash={:02x?} exact_serial={}",digest(&serial12),exact(&serial,&serial12));println!("workers32_2047 work={w32a:?} seconds={d32a:.6} hash={h32early:02x?} archived12_match={early_archive}");println!("workers32_4096 work={w32end:?} seconds={d32end:.6} hash={h32end:02x?} archived12_match={end_archive} exact_serial={exact_serial32}");println!("workers32_2047_repeat work={w32repeat:?} seconds={d32repeat:.6} hash={h32repeat:02x?} equals_first={} archived12_match={}",h32repeat==h32early,h32repeat==ARCHIVED_2047);Ok(())}
fn one(domain:Domain,s:ForceSettings,t:u128)->Result<(Field,ForceWork,f64),SolverError>{let mut p=s.build(domain,CAP)?;evaluate(domain,&mut p,t)}
fn evaluate(domain:Domain,p:&mut impl PrescribedForce,t:u128)->Result<(Field,ForceWork,f64),SolverError>{let mut out=empty(domain);let now=Instant::now();let w=p.evaluate(TickClock::restore(-20,8192,t,8192-t)?,p.limits().ok_or(SolverError::UnknownProviderCost)?,out.each_mut().map(Vec::as_mut_slice))?;Ok((out,w,now.elapsed().as_secs_f64()))}
fn empty(d:Domain)->Field{std::array::from_fn(|_|vec![Complex64::new(0.,0.);d.layout().half_len()])}
fn digest(f:&Field)->[u8;32]{let mut h=Sha256::new();for c in f{for x in c{h.update(x.re.to_bits().to_le_bytes());h.update(x.im.to_bits().to_le_bytes())}}h.finalize().into()}
fn exact(a:&Field,b:&Field)->bool{a.iter().zip(b).all(|(x,y)|x.iter().zip(y).all(|(u,v)|u.re.to_bits()==v.re.to_bits()&&u.im.to_bits()==v.im.to_bits()))}
